function unit(u){if(u.loaded||u.refunded||u.team===1&&!battle.canSee(0,u)||!u.alive&&battle.time-u.deathTime>1.8||!visible(u)&&!u.def.building)return;const selected=battle.selection.includes(u.id),alpha=!u.alive?Math.max(0,1-(battle.time-u.deathTime)/1.8):u.cloaked?.42:u.burrowed&&u.type!==103?.3:1;if(selected&&u.alive){ctx.strokeStyle='#79f880';ctx.lineWidth=1.3/camera.zoom;ctx.beginPath();ctx.ellipse(u.x,u.y+u.r*.55,u.r+5,(u.r+5)*.48,0,0,Math.PI*2);ctx.stroke();if(u.goal){ctx.strokeStyle='#8ece9844';ctx.setLineDash([5,6]);ctx.beginPath();ctx.moveTo(u.x,u.y);ctx.lineTo(u.goal.x,u.goal.y);ctx.stroke();ctx.setLineDash([])}}const g=data.graphics[u.def.image];if(g&&u.alive)for(const sh of g.shadows||[])sprite(sh,0,u.x+2,u.y+3,'idle',u.animTime,u.direction,.35);sprite(u.def.image,u.team,u.x,u.y,u.action,u.animTime,u.direction,alpha);const sub=u.def.subunit!==null?data.units[u.def.subunit]:null;if(sub&&u.alive)sprite(sub.image,u.team,u.x,u.y,u.action,u.animTime,u.direction,alpha);if(u.alive&&(selected||u.team===1||u.hp<u.def.hp)){const w=Math.max(22,Math.min(60,u.r*2+4)),h=3/camera.zoom,y=u.y-u.r-10/camera.zoom;ctx.fillStyle='#071114';ctx.fillRect(u.x-w/2-1,y-1,w+2,h+2);ctx.fillStyle=u.hp/u.def.hp>.55?'#74cb6c':u.hp/u.def.hp>.25?'#e6c565':'#e78066';ctx.fillRect(u.x-w/2,y,w*clamp(u.hp/(u.maxHp||u.def.hp),0,1),h);if(u.def.shield){ctx.fillStyle='#5b9fd3';ctx.fillRect(u.x-w/2,y-4/camera.zoom,w*u.shield/u.def.shield,2/camera.zoom)}if(u.def.energy&&selected){ctx.fillStyle='#b183d2';ctx.fillRect(u.x-w/2,y+5/camera.zoom,w*u.energy/u.def.energy,2/camera.zoom)}}if(u.matrix>0||u.buffs.stasis>0||u.buffs.lockdown>0){ctx.strokeStyle=u.matrix>0?'#c3e9a388':u.buffs.stasis>0?'#b7deea':'#e9ca64';ctx.lineWidth=1.5;ctx.strokeRect(u.x-u.r-3,u.y-u.r-3,u.r*2+6,u.r*2+6)}}
function tile(x,y){const salt=((x*73856093)^(y*19349663))>>>0,xx=x*32,yy=y*32;if(battle.map.rocks.some(r=>xx+16>=r.x&&xx+16<r.x+r.w&&yy+16>=r.y&&yy+16<r.y+r.h))return 85+salt%6;if(yy<410&&Math.abs(xx-640)<210)return 142+salt%5;if(Math.abs(xx-640)<85||yy>900&&yy<1020&&xx>430&&xx<920)return 16+salt%7;return 96+salt%8}
function minimap(){const sx=mini.width/1280,sy=mini.height/2048;mc.fillStyle='#162b20';mc.fillRect(0,0,160,220);mc.fillStyle='#857b5155';for(const r of battle.map.rocks)mc.fillRect(r.x*sx,r.y*sy,r.w*sx,r.h*sy);for(let y=0;y<64;y++)for(let x=0;x<40;x++)if(!battle.fog[y*40+x]){mc.fillStyle=battle.explored[y*40+x]?'#030c1066':'#02080cdd';mc.fillRect(x*32*sx,y*32*sy,32*sx+.5,32*sy+.5)}for(const u of battle.units)if(u.alive&&!u.loaded&&(u.team===0||battle.canSee(0,u))){mc.fillStyle=u.team?'#e78a6e':battle.selection.includes(u.id)?'#e7e5af':'#87d17d';const s=u.def.building?5:2;mc.fillRect(u.x*sx-s/2,u.y*sy-s/2,s,s)}if(battle.core?.alive){mc.fillStyle='#e3c789';mc.fillRect(battle.core.x*sx-2,battle.core.y*sy-2,4,4)}const a=toWorld(0,63),b=toWorld(W,H-panelHeight());mc.strokeStyle='#c7d4bd';mc.strokeRect(a.x*sx,a.y*sy,(b.x-a.x)*sx,(b.y-a.y)*sy)}
function render(now){const realDt=last?Math.min(.15,(now-last)/1000):1/60;last=now;const dt=document.hidden?0:realDt;battle.update(dt);hudTime+=realDt;if(hudTime>.15){hudTime=0;hudUI();if(map)minimap()}ctx.setTransform(DPR,0,0,DPR,0,0);ctx.fillStyle='#10191c';ctx.fillRect(0,0,W,H);limitCamera();ctx.save();ctx.translate(W/2,cy());ctx.scale(camera.zoom,camera.zoom);ctx.translate(-camera.x,-camera.y);const a=toWorld(0,0),b=toWorld(W,H),x0=Math.max(0,Math.floor(a.x/32)),x1=Math.min(40,Math.ceil(b.x/32)),y0=Math.max(0,Math.floor(a.y/32)),y1=Math.min(64,Math.ceil(b.y/32));for(let y=y0;y<y1;y++)for(let x=x0;x<x1;x++){const n=tile(x,y);ctx.drawImage(terrain,n%16*64,Math.floor(n/16)*64,64,64,x*32,y*32,32,32)}if(battle.phase==='prep'){ctx.strokeStyle='#85c89788';ctx.lineWidth=1/camera.zoom;ctx.setLineDash([7,8]);ctx.strokeRect(60,1560,1160,420);ctx.setLineDash([]);ctx.font='11px system-ui';ctx.textAlign='center';ctx.fillStyle='#bfd5b6';ctx.fillText('아군 출발 지역 · 드래그로 배치',640,1578)}for(const area of battle.areas){ctx.save();ctx.globalAlpha=Math.min(.3,area.left*.6);ctx.fillStyle={storm:'#89b8f7',swarm:'#ccad50',web:'#dce6e9',plague:'#ae3840',ensnare:'#94c45f',stasis:'#bce0ed'}[area.kind]||'#9bbed2';ctx.beginPath();ctx.arc(area.x,area.y,area.r,0,Math.PI*2);ctx.fill();ctx.restore();if(area.kind==='storm')sprite(525,0,area.x,area.y,'idle',area.duration-area.left)}for(const u of [...battle.units].sort((a,b)=>Number(a.def.air)-Number(b.def.air)||a.y-b.y))unit(u);for(const p of battle.projectiles){const dir=(Math.round(Math.atan2(p.endX-p.x,p.y-p.endY)*16/Math.PI)+32)%32;if(!sprite(p.image,p.team,p.x,p.y,'idle',p.elapsed,dir)){ctx.fillStyle=p.spell?'#ffe39b':'#b1d9e6';ctx.beginPath();ctx.arc(p.x,p.y,p.spell?4:2,0,Math.PI*2);ctx.fill()}}for(const f of battle.effects)sprite(f.image,0,f.x,f.y,'idle',(f.duration-f.left)*1.1,0,Math.min(1,f.left*4));for(const beam of beams){beam.left-=realDt;ctx.strokeStyle=beam.team?'#f8c28d88':'#dfef9a88';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(beam.from.x,beam.from.y);ctx.lineTo(beam.to.x,beam.to.y);ctx.stroke()}beams=beams.filter(x=>x.left>0);if(battle.phase!=='title')for(let y=y0;y<y1;y++)for(let x=x0;x<x1;x++)if(!battle.fog[y*40+x]){ctx.fillStyle=battle.explored[y*40+x]?'#030c10a9':'#030a10e8';ctx.fillRect(x*32,y*32,32.5,32.5)}if(battle.core?.alive){ctx.save();ctx.translate(battle.core.x,battle.core.y-85);ctx.rotate(Math.PI/4);ctx.fillStyle='#e2c587';ctx.fillRect(-5,-5,10,10);ctx.restore()}for(const m of markers){m.left-=realDt;ctx.globalAlpha=Math.min(1,m.left*2);ctx.strokeStyle=m.attack?'#e99b76':'#9cdd91';ctx.lineWidth=1.8/camera.zoom;ctx.beginPath();ctx.arc(m.x,m.y,8+(1-m.left)*15,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1}markers=markers.filter(m=>m.left>0);if(gesture?.kind==='box'){const s=gesture.world,e=toWorld(gesture.current.x,gesture.current.y);ctx.fillStyle='#83e7921c';ctx.strokeStyle='#9ef69a';ctx.lineWidth=1/camera.zoom;ctx.fillRect(s.x,s.y,e.x-s.x,e.y-s.y);ctx.strokeRect(s.x,s.y,e.x-s.x,e.y-s.y)}ctx.restore();if(battle.paused&&battle.phase==='battle'&&$('modal').hidden){ctx.fillStyle='#07151aa9';ctx.fillRect(0,0,W,H);ctx.fillStyle='#deddbb';ctx.font='bold 20px system-ui';ctx.textAlign='center';ctx.fillText('일시 정지',W/2,cy())}requestAnimationFrame(render)}
function modal(kind,html){if(battle?.menuOpen)battle.closeMenu();pausedBefore=battle?.paused||false;if(battle?.phase==='battle')battle.paused=true;modalKind=kind;$('modalContent').innerHTML=html;$('modal').hidden=false}
function closeModal(){if(modalKind==='result')return;$('modal').hidden=true;if(battle?.phase==='battle')battle.paused=pausedBefore;modalKind=''}$('closeModal').onclick=closeModal;
function help(){modal('help',`<div class="eyebrow">FIELD MANUAL</div><h2>모바일 전술 조작</h2><ul><li><b>터치</b>: 아군 선택. 빠르게 두 번 터치하면 화면 안의 같은 종류 전체 선택.</li><li><b>빈 땅을 길게 누르고 드래그</b>: 범위 선택. 하단 ‘범위’를 켜면 바로 드래그 선택.</li><li><b>스와이프</b>: 카메라 이동. 두 손가락 이동과 핀치 확대 지원.</li><li><b>명령</b>: 메뉴가 열리는 순간 0.5×. 지점·대상을 지정하거나 취소하면 1.0×.</li><li><b>Ctrl → 숫자</b>: 부대 지정. 숫자만 누르면 호출, 두 번 누르면 부대 위치로 이동.</li><li><b>준비 중</b>: 유닛 드래그로 재배치. 선택 후 전액 환불 가능.</li></ul><h3>PC 조작</h3><p>M·A·P: 이동·공격·패트롤 / H·S: 홀드·정지<br>숫자: 부대 호출 / Ctrl+숫자: 부대 지정<br>F2: 전체 선택 / Space: 일시 정지 / Esc: 취소</p><button class="primary" id="helpDone">확인</button>`);$('helpDone').onclick=closeModal}$('help').onclick=help;
function settingsModal(){modal('settings',`<div class="eyebrow">COMMAND CENTER</div><h2>설정</h2>${[['배경음악','bgm'],['효과음','sfx'],['유닛 음성','voice']].map(([label,key])=>`<label>${label}<input id="vol-${key}" type="range" min="0" max="1" step=".01" value="${settings[key]}"></label>`).join('')}<label>렌더링<select id="quality"><option value="auto" ${settings.quality==='auto'?'selected':''}>자동 · 선명하게</option><option value="low" ${settings.quality==='low'?'selected':''}>절전 · 낮은 해상도</option></select></label><div class="row"><button id="pause">${pausedBefore?'전투 재개':'일시 정지 유지'}</button><button id="manual">조작 방법</button><button id="leave">작전 나가기</button></div><h3>편성 프리셋</h3><div class="row"><button id="savePreset">현재 편성 저장</button><button id="loadPreset" ${battle.phase!=='prep'?'disabled':''}>편성 불러오기</button></div><p>미니스타 ${VERSION} · 리마스터 ${data.sourceBuild}<br>설정과 전투 기록은 기기에 저장됩니다.</p>`);for(const key of ['bgm','sfx','voice'])$('vol-'+key).oninput=e=>{settings[key]=Number(e.target.value);save('settings',settings);if(bgm)bgm.volume=settings.bgm;if(voice)voice.volume=settings.voice};$('quality').onchange=e=>{settings.quality=e.target.value;save('settings',settings);resize()};$('pause').onclick=()=>{pausedBefore=!pausedBefore;closeModal()};$('manual').onclick=()=>{const p=pausedBefore;help();pausedBefore=p};$('leave').onclick=()=>{modalKind='';$('modal').hidden=true;bgm?.pause();newBattle()};$('savePreset').onclick=()=>{const counts={};for(const u of battle.allies)counts[u.type]=(counts[u.type]||0)+1;save('preset.'+race,counts);toast('현재 생존 병력 구성을 저장했습니다.')};$('loadPreset').onclick=()=>{const preset=read('preset.'+race,null);if(!preset){toast('저장된 편성이 없습니다.');return}for(const u of [...battle.allies])battle.refund([u.id]);for(const [type,count] of Object.entries(preset)){const qty=data.units[type]?.qty||1;for(let i=0;i<count;i+=qty)battle.buy(Number(type))}closeModal();toast('자원·보급 한도 안에서 편성을 불러왔습니다.')}}$('settings').onclick=settingsModal;
function resultModal(r){modal('result',`<div class="eyebrow">OPERATION COMPLETE</div><h2 style="font-size:32px;color:${r.win?'#e4d28b':'#de987f'}">${r.win?'승리':'패배'}</h2><p>${r.reason}</p><div class="stats">${[['전투 시간',Math.floor(r.time/60)+':'+String(Math.floor(r.time%60)).padStart(2,'0')],['생산한 병력',r.produced+'기'],['생존 병력',r.survivors+'기'],['적 처치',r.kills+'기'],['아군 손실',r.losses+'기'],['총 피해량',Math.round(r.damage).toLocaleString()]].map(([a,b])=>`<div><span>${a}</span><b>${b}</b></div>`).join('')}</div><button id="retry" class="primary">다시 출전하기</button><button id="toTitle" class="secondary">종족 선택으로</button>`);$('retry').onclick=()=>{modalKind='';$('modal').hidden=true;newBattle();battle.begin();toggleShop(true)};$('toTitle').onclick=()=>{modalKind='';$('modal').hidden=true;newBattle()}}
$('records').onclick=()=>{const records=read('records',[]);modal('records',`<div class="eyebrow">BATTLE LOG</div><h2>전투 기록</h2>${records.length?records.slice(0,20).map(r=>`<div class="log"><span>${r.win?'승리':'패배'} · ${labels[r.race]}<br><small>${new Date(r.date).toLocaleDateString('ko-KR')} · ${Math.floor(r.time/60)}분 ${Math.floor(r.time%60)}초</small></span><b>${r.kills} 처치</b></div>`).join(''):'<p>첫 작전에 출전해 기록을 남겨보세요.</p>'}`)};
function raceUI(){for(const el of document.querySelectorAll('[data-race]'))el.classList.toggle('active',el.dataset.race===race);$('gasIcon').src=iconResource({terran:1,zerg:2,protoss:3}[race]);$('supplyIcon').src=iconResource({terran:4,zerg:5,protoss:6}[race])}const iconResource=n=>'assets/icons/resource_'+String(n).padStart(3,'0')+'.png';for(const el of document.querySelectorAll('[data-race]'))el.onclick=()=>{race=el.dataset.race;save('race',race);raceUI()};$('deploy').onclick=()=>{newBattle();battle.begin();toggleShop(true)};
addEventListener('keydown',e=>{if(!battle)return;if(e.key==='Escape'){e.preventDefault();if(battle.menuOpen)battle.closeMenu();else if(!$('modal').hidden)closeModal();else toggleShop(false);return}if(!$('modal').hidden||['title','result'].includes(battle.phase))return;if(e.key===' '){e.preventDefault();battle.paused=!battle.paused;toast(battle.paused?'일시 정지':'전투 재개');return}if(e.key==='Enter'&&battle.phase==='prep'){battle.start();return}if(e.key==='F2'){e.preventDefault();$('selectAll').click();return}if(/^\d$/.test(e.key)){e.preventDefault();const i=e.key==='0'?9:Number(e.key)-1;if(e.ctrlKey||ctrl){if(battle.assignGroup(i))ctrl=false;groupsUI()}else battle.recallGroup(i);return}const key={m:'move',a:'attack',p:'patrol',h:'hold',s:'stop',b:'burrow'}[e.key.toLowerCase()];if(key&&battle.phase==='battle'&&battle.selected.length){e.preventDefault();if(!battle.menuOpen)openMenu();battle.chooseCommand(key)}});
document.addEventListener('visibilitychange',()=>{last=0;if(document.hidden)bgm?.pause();else if(battle?.phase==='battle')bgm?.play().catch(()=>{})});
async function offlineRegister(){if(!('serviceWorker'in navigator)){$('offlineStatus').textContent='localhost에서 접속하면 오프라인 준비를 사용할 수 있어요.';return}try{registration=await navigator.serviceWorker.register('./sw.js');navigator.serviceWorker.addEventListener('message',e=>{if(e.data.type==='CACHE_PROGRESS')$('offlineStatus').textContent=`오프라인 준비 ${e.data.done}/${e.data.total}`;if(e.data.type==='CACHE_DONE'){$('offlineStatus').textContent='오프라인 준비 완료 · 홈 화면에 추가하세요';toast('오프라인 리소스 저장 완료')}if(e.data.type==='CACHE_ERROR'){$('offlineStatus').textContent='저장 실패 · 여유 공간과 서버 연결을 확인하세요.';toast('오프라인 준비를 다시 시도하세요.')}})}catch{$('offlineStatus').textContent='localhost 접속에서 오프라인 설치를 사용할 수 있어요.'}}
$('offline').onclick=async()=>{if(!registration)await offlineRegister();if(registration){const r=await navigator.serviceWorker.ready;r.active?.postMessage({type:'CACHE_ALL'});$('offlineStatus').textContent='오프라인 리소스를 준비하고 있습니다…'}};
async function boot(){try{data=await fetch('assets/data.json').then(r=>{if(!r.ok)throw Error('전투 데이터를 읽을 수 없습니다.');return r.json()});terrain=await loadImage('assets/terrain.webp');if(!terrain)throw Error('지형 이미지를 읽을 수 없습니다.');newBattle();raceUI();$('boot').hidden=true;await offlineRegister();requestAnimationFrame(render)}catch(e){$('bootText').textContent=e.message+' · start.sh로 서버를 실행한 뒤 접속하세요.';console.error(e)}}boot();
